import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.Co19Uros.js";const u=JSON.parse('{"title":"@rapiq/cache","description":"","frontmatter":{},"headers":[],"relativePath":"packages/cache.md","filePath":"packages/cache.md","lastUpdated":1793176684000}'),c={name:"packages/cache.md"};function d(o,e,i,h,n,l){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="rapiq-cache" tabindex="-1">@rapiq/cache <a class="header-anchor" href="#rapiq-cache" aria-label="Permalink to &quot;@rapiq/cache&quot;">​</a></h1><p>A tag-invalidated result cache for rapiq queries. A cached result depends on every row it holds and on the membership of the sets it selected from, so a stored value carries <strong>tags</strong> (a collection, a scope, a record), every tag has a <strong>version</strong> on one logical clock, and a write bumps the tags it owns. A read whose entry carries a bumped tag is a miss.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @rapiq/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @rapiq/cache</span></span></code></pre></div><p>The full walkthrough is the <a href="/guide/cache.html">Caching Query Results</a> guide.</p><h2 id="what-s-inside" tabindex="-1">What&#39;s inside <a class="header-anchor" href="#what-s-inside" aria-label="Permalink to &quot;What&#39;s inside&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Exports</th><th>Guide</th></tr></thead><tbody><tr><td><strong>Cache</strong></td><td><code>TaggedCache</code> (<code>remember</code>, <code>invalidate</code>, <code>drop</code>), <code>ITaggedCache</code></td><td><a href="/guide/cache.html#reading-through-the-cache">Reading through the cache</a></td></tr><tr><td><strong>Tags</strong></td><td><code>buildCollectionTag</code>, <code>buildRecordTag</code>, <code>buildScopedTag</code>, <code>isScopedTagValue</code></td><td><a href="/guide/cache.html#vocabulary">Vocabulary</a></td></tr><tr><td><strong>Query tags</strong></td><td><code>collectQueryTags</code>, <code>isCacheable</code>, <code>rememberQuery</code>, <code>QueryTagsInput</code>, <code>RememberQueryInput</code>, <code>QueryCaseSensitive</code></td><td><a href="/guide/cache.html#which-tags-a-query-yields">Which tags a query yields</a></td></tr><tr><td><strong>Drivers</strong></td><td><code>ICacheDriver</code>, <code>CacheEntry</code>, <code>MemoryCacheDriver</code>, <code>CACHE_MAX_TTL_DEFAULT</code>, <code>isCacheTtlValid</code>, <code>clampCacheTtl</code>, <code>isCacheTagWellFormed</code></td><td><a href="/guide/cache.html#the-driver-contract">The driver contract</a></td></tr><tr><td><strong>Errors</strong></td><td><code>CacheError</code>, <code>isCacheError</code></td><td><a href="/guide/cache.html#errors">Errors</a></td></tr></tbody></table><p>The cache key is the caller&#39;s, and it must encode every input that selects the result: the executed query, <code>fields</code>, and every path parameter (the <code>:id</code> of <code>GET /roles/:id</code>). See <a href="/guide/cache.html#the-cache-key">the cache key</a>. A string filter value scopes only when <code>caseSensitive</code> carries exactly what you pass to <code>adapter.execute(query, { caseSensitive })</code>.</p><h2 id="the-typeorm-write-side" tabindex="-1">The TypeORM write side <a class="header-anchor" href="#the-typeorm-write-side" aria-label="Permalink to &quot;The TypeORM write side&quot;">​</a></h2><p><code>CacheInvalidationSubscriber</code> bumps the tags of every row TypeORM writes, after the transaction that wrote it committed. It is its own entry, so the root types never import from <code>typeorm</code>:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { CacheInvalidationSubscriber } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@rapiq/cache/typeorm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><code>typeorm</code> is an optional peer dependency for the types of that entry alone; the class imports nothing from <code>typeorm</code> at runtime. Push the instance onto <code>dataSource.subscribers</code> after every <code>initialize()</code>. See <a href="/guide/cache.html#the-typeorm-write-side">The TypeORM write side</a> and <a href="/guide/cache.html#what-reaches-a-scoped-reader">what reaches a scoped reader</a>.</p><h2 id="shared-stores" tabindex="-1">Shared stores <a class="header-anchor" href="#shared-stores" aria-label="Permalink to &quot;Shared stores&quot;">​</a></h2><p>The memory driver serves one process. For a store shared between processes use <a href="/packages/cache-redis.html">@rapiq/cache-redis</a>, which implements the same <code>ICacheDriver</code> contract and runs the same contract suite.</p>',13)])])}const g=a(c,[["render",d]]);export{u as __pageData,g as default};
